widget.solution:
from math import gcd


def is_prime(n):
    return n > 1 and all(n % d for d in range(2, int(n ** 0.5) + 1))


def fermat_liars(n):
    """Sorted bases 1 <= a < n, coprime to n, with a^(n-1) = 1 mod n."""
    return [a for a in range(1, n)
            if gcd(a, n) == 1 and pow(a, n - 1, n) == 1]


def is_carmichael(n):
    """Composite n for which every coprime base is a liar."""
    if n < 3 or is_prime(n):
        return False
    units = [a for a in range(1, n) if gcd(a, n) == 1]
    return len(fermat_liars(n)) == len(units)
